/* C translation of Tim Follin's Ghouls'n'Ghosts playroutine.
 *
 * The original image comes from ghouls_data.h, generated byte-for-byte from
 * the PSID. It is held in ram[] at its original addresses: music init copies
 * blocks of it to $730e+ and $9xxx, and the 16-bit pointers in the data are
 * original addresses, so all table and pattern reads go through peek().
 */
#include <stddef.h>
#include <stdint.h>

#include "driver.h"
#include "ghouls_data.h"

#define SID ((volatile uint8_t *)0xd400)
enum { FREQ_L, FREQ_H, PW_L, PW_H, CTRL, VOICE_REGS = 7 };
enum { SID_REGS = 0x1d, FILTER_L = 0x15, FILTER_H = 0x16, VOLUME = 0x18 };
enum { GATE = 1, PULSE_WAVE = 0x40 };

/* Original memory below the BASIC ROM, from the image load address. */
#define RAM_END 0xa000
static uint8_t ram[RAM_END - IMAGE_ORG] = {IMAGE};

/* Tables of the original, by address. */
#define BLOCK_SRC 0x29e7     /* word per block: copy source */
#define BLOCK_DST 0x29fb     /* word per block: copy destination */
#define BLOCK_LEN 0x2a30     /* word per block: copy length */
#define SONG_INDEX 0x2a0f    /* per song: column of SONG_PTRS */
#define SONG_BLOCK_A 0x2a1a  /* per song: first block to copy */
#define SONG_BLOCK_B 0x2a25  /* per song: second block to copy */
#define SONG_PTRS 0x730e     /* per voice: 7 low then 7 high bytes */
#define EFFECT_LO 0x6df7     /* per effect: list of (2*voice, pointer) */
#define EFFECT_HI 0x6e0d     /*   terminated by a byte >= $80 */
#define FREQ_LO 0x6d35       /* per note */
#define FREQ_HI 0x6d96       /* per note */
#define PULSE_DEFAULT 0x6a05 /* word per voice: pulse when a sweep gives 0 */
#define STACK 0x6b1f         /* per voice: 3 low then 3 high return bytes */
#define HR_FREQ 0x6bda       /* word, voice stride HR_STRIDE: restart freq */
#define HR_STRIDE 0x1b
#define EFFECT_FIRST 11  /* songs from here are sound effects */
#define EFFECT_BASE 10   /* effect number = song - EFFECT_BASE */
#define PULSE_MIN 0x0064 /* pulse sweep bounces below this */
#define PULSE_MAX 0x0f9b /* and at or above this */

/* Pattern bytes: 0 extends the note, 1-$7f is a note, then its duration
 * unless fixed. Commands, with their argument bytes: */
enum {
  CMD_PULSE = 0x80, /* speed, start lo, hi */
  CMD_LOOP_END,     /* back to CMD_LOOP until its count runs out */
  CMD_LOOP,         /* count */
  CMD_HARD_GATE,    /* gate time: gate on at each note */
  CMD_FIXED_DUR,    /* duration of the following notes, 0 = per note */
  CMD_REGS,         /* (register, value)... terminated by a byte >= $80 */
  CMD_STOP,         /* voice off */
  CMD_GOTO,         /* address lo, hi */
  CMD_FILTER,       /* speed, direction, cutoff, min, max (lo, hi each) */
  CMD_FILTER_VOICE, /* this voice's notes restart the filter sweep */
  CMD_GOSUB,        /* address lo, hi */
  CMD_RETURN,
  CMD_TRANSPOSE,     /* semitones */
  CMD_CTRL,          /* control register; pulse waveform starts a sweep */
  CMD_VIBRATO,       /* delay, speed, width, direction */
  CMD_HARD_RESTART,  /* frames, control, freq lo, hi */
  CMD_GATE_OFF,      /* frames before the note end */
  CMD_TRILL,         /* interval, frames up, frames down */
  CMD_PORTAMENTO,    /* speed */
  CMD_RAW_NOTE,      /* the next note is not transposed */
  CMD_DEFAULT_PULSE, /* lo, lo again: both bytes go to the low byte */
};

/* Zero-page state $21-$95 of the original, in its order. */
static struct state {
  uint16_t ptr[3]; /* pattern read pointer */
  uint8_t dur[3];  /* frames left of the note */
  uint8_t ctrl[3]; /* control register */
  uint8_t loop_count[3];
  uint16_t loop_ptr[3];
  uint8_t hard_gate[3];  /* notes gate on */
  uint8_t gate_time[3];  /* frames from a note to gate off */
  uint8_t gate_count[3]; /* frames left to gate off */
  uint16_t pulse[3];
  uint16_t pulse_start[3]; /* reloaded at each note if nonzero */
  uint8_t pulse_speed[3];
  uint8_t transpose[3];
  uint8_t hr_frames[3];  /* hard restart length, 0 = none */
  uint8_t hr_ctrl[3];    /* control register during hard restart */
  uint8_t vib_delay[3];  /* 0 = no vibrato */
  uint8_t trill_up[3];   /* frames on the upper note */
  uint8_t trill_down[3]; /* frames on the lower note */
  uint8_t trill_count[3];
  uint8_t porta_speed[3]; /* 0 = no portamento */
  uint8_t note[3];
  uint8_t depth[3]; /* gosub stack depth */
  uint8_t porta_target[3];
  uint16_t cutoff;
  uint16_t cutoff_start; /* reloaded at the filter voice's notes */
  uint8_t cutoff_speed;
  uint8_t filter_voice;
  uint8_t freq_lo[3];
  uint8_t freq_hi[3];
  uint8_t active[3];   /* bit 7 = playing */
  uint8_t vib_wait[3]; /* frames to vibrato start */
  uint8_t vib_dir_start[3];
  uint8_t vib_count[3]; /* frames to direction change */
  uint8_t vib_width[3];
  uint8_t vib_speed[3];
  uint8_t hr_count[3]; /* frames left of hard restart */
  uint8_t gate_off[3]; /* gate off when dur reaches this */
  uint8_t trill_step[3];
} zp;

/* State the original keeps in its own instruction operands, with their
 * values in the image: one operand per voice copy ($1ED, $1EF apart). */
static uint8_t vib_dir[3];               /* 0 = down */
static uint8_t trill_phase[3];           /* $ff = upper note */
static uint8_t pulse_dir[3] = {1, 1, 1}; /* 0 down, bit 7 up, else none */
static uint8_t pulse_dir_start[3] = {1, 1, 1};
static uint8_t raw_notes[3];        /* untransposed notes: -count */
static uint8_t cutoff_dir_start[3]; /* per filter voice */
static uint8_t fixed_dur[3];        /* 0 = duration per note */
static uint8_t cutoff_dir;          /* 0 = down */
static uint8_t cutoff_min_lo, cutoff_min_hi, cutoff_max_lo, cutoff_max_hi;

static uint8_t peek(uint16_t a) { return ram[a - IMAGE_ORG]; }
static void poke(uint16_t a, uint8_t b) { ram[a - IMAGE_ORG] = b; }
static uint16_t peek16(uint16_t a) { return peek(a) | peek(a + 1) << 8; }

static void set_note(volatile uint8_t *reg, uint8_t v, uint8_t n) {
  zp.note[v] = n;
  reg[FREQ_L] = zp.freq_lo[v] = peek(FREQ_LO + n);
  reg[FREQ_H] = zp.freq_hi[v] = peek(FREQ_HI + n);
}

static void vibrato(volatile uint8_t *reg, uint8_t v) {
  uint8_t lo = zp.freq_lo[v], hi = zp.freq_hi[v], s = zp.vib_speed[v];
  uint8_t dir = vib_dir[v], down = !dir;
  if (dir) {
    lo += s;
    if (lo < s && !++hi)
      down = 1; /* carry into a wrapped high byte falls into the down path */
  }
  if (down) {
    if (lo < s)
      --hi;
    lo -= s;
  }
  reg[FREQ_L] = zp.freq_lo[v] = lo;
  reg[FREQ_H] = zp.freq_hi[v] = hi;
  if (!--zp.vib_count[v] && zp.vib_width[v]) {
    zp.vib_count[v] = zp.vib_width[v] << 1;
    vib_dir[v] = ~dir;
  }
}

/* Sweep between PULSE_MIN and PULSE_MAX, reversing at either bound. */
static void pulse_sweep(volatile uint8_t *reg, uint8_t v) {
  uint16_t pw = zp.pulse[v];
  uint8_t s = zp.pulse_speed[v], down = !pulse_dir[v];
  if (!down && !(pulse_dir[v] & 0x80))
    return;
  for (;;) {
    if (down) {
      pw -= s;
      if (!(pw & 0x8000) && pw >= PULSE_MIN)
        break;
      if (!(--pulse_dir[v] & 0x80)) {
        zp.pulse[v] = pw;
        return;
      }
    }
    pw += s;
    if (pw < PULSE_MAX)
      break;
    ++pulse_dir[v];
    down = 1;
  }
  zp.pulse[v] = pw;
  reg[PW_L] = pw;
  reg[PW_H] = pw >> 8;
}

/* Read pattern bytes up to the next note. */
static void read_pattern(volatile uint8_t *reg, uint8_t v) {
  uint16_t p;
  uint8_t y, b, x;
#define ARG() peek(p + y++)
  for (;;) {
    p = zp.ptr[v];
    y = 1;
    b = peek(p);
    if (!b) {
      zp.gate_count[v] = zp.gate_time[v];
      break;
    }
    if (!(b & 0x80)) {
      if (!raw_notes[v] || ++raw_notes[v])
        b += zp.transpose[v];
      if (zp.porta_speed[v]) {
        zp.porta_target[v] = b;
        b = zp.note[v];
      }
      set_note(reg, v, b);
      zp.trill_count[v] = zp.trill_up[v];
      if (zp.vib_delay[v]) {
        zp.vib_wait[v] = zp.vib_delay[v];
        vib_dir[v] = zp.vib_dir_start[v];
        zp.vib_count[v] = zp.vib_width[v];
      }
      trill_phase[v] = 0;
      zp.gate_count[v] = zp.gate_time[v];
      if (zp.pulse_start[v]) {
        zp.pulse[v] = zp.pulse_start[v];
        pulse_dir[v] = pulse_dir_start[v];
      }
      if (zp.filter_voice == v && zp.cutoff_start) {
        zp.cutoff = zp.cutoff_start;
        cutoff_dir = cutoff_dir_start[v];
      }
      if (zp.hard_gate[v]) {
        b = zp.ctrl[v];
        if ((x = zp.hr_frames[v])) {
          zp.hr_count[v] = x;
          reg[FREQ_L] = peek(HR_FREQ + HR_STRIDE * v);
          reg[FREQ_H] = peek(HR_FREQ + HR_STRIDE * v + 1);
          b = zp.hr_ctrl[v];
        }
        reg[CTRL] = b | GATE;
      }
      break;
    }
    /* 6502: per-voice handler copies at $6858-$6C75, dispatched through split
     * tables $6C37/$6C76,X and jumping back into their voice copy. */
    switch (b) {
    case CMD_PULSE:
      zp.pulse_speed[v] = ARG();
      b = ARG();
      zp.pulse[v] = zp.pulse_start[v] = b | ARG() << 8;
      if (!zp.pulse[v])
        zp.pulse[v] = peek16(PULSE_DEFAULT + 2 * v);
      break;
    case CMD_LOOP_END:
      if (--zp.loop_count[v]) {
        zp.ptr[v] = zp.loop_ptr[v];
        continue;
      }
      break;
    case CMD_LOOP:
      zp.loop_count[v] = ARG();
      zp.loop_ptr[v] = p + y;
      break;
    case CMD_HARD_GATE:
      zp.hard_gate[v] = 1;
      zp.gate_time[v] = ARG();
      break;
    case CMD_FIXED_DUR:
      fixed_dur[v] = ARG();
      break;
    case CMD_REGS:
      x = peek(p + y);
      do {
        ++y;
        SID[x] = ARG();
        x = peek(p + y);
      } while (!(x & 0x80));
      ++y;
      break;
    case CMD_STOP:
      ++zp.active[v];
      return;
    case CMD_GOSUB:
      x = zp.depth[v]++;
      poke(STACK + 6 * v + x, p + 3);
      poke(STACK + 6 * v + 3 + x, (p + 3) >> 8);
      /* fall through */
    case CMD_GOTO:
      zp.ptr[v] = peek16(p + 1);
      continue;
    case CMD_RETURN:
      x = --zp.depth[v];
      zp.ptr[v] = peek(STACK + 6 * v + x) | peek(STACK + 6 * v + 3 + x) << 8;
      continue;
    case CMD_FILTER:
      zp.cutoff_speed = ARG();
      cutoff_dir_start[v] = ARG();
      b = ARG();
      zp.cutoff = zp.cutoff_start = b | ARG() << 8;
      cutoff_min_lo = ARG();
      cutoff_min_hi = ARG();
      cutoff_max_lo = ARG();
      cutoff_max_hi = ARG();
      break;
    case CMD_FILTER_VOICE:
      zp.filter_voice = v;
      break;
    case CMD_TRANSPOSE:
      zp.transpose[v] = ARG();
      break;
    case CMD_CTRL:
      reg[CTRL] = zp.ctrl[v] = b = ARG();
      pulse_dir[v] = pulse_dir_start[v] = b & PULSE_WAVE ? 0xff : 1;
      break;
    case CMD_VIBRATO:
      zp.vib_delay[v] = ARG();
      zp.vib_speed[v] = ARG();
      zp.vib_width[v] = ARG();
      zp.vib_dir_start[v] = ARG();
      break;
    case CMD_HARD_RESTART:
      zp.hr_frames[v] = ARG();
      zp.hr_ctrl[v] = ARG();
      poke(HR_FREQ + HR_STRIDE * v, ARG());
      poke(HR_FREQ + HR_STRIDE * v + 1, ARG());
      break;
    case CMD_GATE_OFF:
      zp.gate_off[v] = ARG();
      break;
    case CMD_TRILL:
      zp.trill_step[v] = ARG();
      zp.trill_up[v] = ARG();
      zp.trill_down[v] = ARG();
      break;
    case CMD_PORTAMENTO:
      zp.porta_speed[v] = ARG();
      break;
    case CMD_RAW_NOTE:
      --raw_notes[v];
      break;
    case CMD_DEFAULT_PULSE:
      poke(PULSE_DEFAULT + 2 * v, ARG());
      poke(PULSE_DEFAULT + 2 * v, ARG());
      break;
    }
    zp.ptr[v] = p + y;
  }
  if (!(b = fixed_dur[v]))
    b = ARG();
  zp.dur[v] = b;
  zp.ptr[v] = p + y;
#undef ARG
}

static void play_voice(uint8_t v) {
  volatile uint8_t *reg = SID + VOICE_REGS * v;
  uint8_t n;
  if (!(zp.active[v] & 0x80))
    return;
  if (zp.hr_count[v] && !--zp.hr_count[v]) {
    reg[FREQ_L] = zp.freq_lo[v];
    reg[FREQ_H] = zp.freq_hi[v];
    if (zp.hard_gate[v])
      reg[CTRL] = zp.ctrl[v] | GATE;
  }
  if (zp.vib_delay[v] && (!zp.vib_wait[v] || !--zp.vib_wait[v]))
    vibrato(reg, v);
  n = zp.note[v];
  if (zp.trill_count[v] && !--zp.trill_count[v]) {
    if ((trill_phase[v] = ~trill_phase[v])) {
      zp.trill_count[v] = zp.trill_up[v];
      n += zp.trill_step[v];
    } else {
      zp.trill_count[v] = zp.trill_down[v];
      n -= zp.trill_step[v];
    }
    set_note(reg, v, n);
  } else if (zp.porta_speed[v] && n != zp.porta_target[v]) {
    uint8_t t = zp.porta_target[v];
    if (n < t) {
      n += zp.porta_speed[v];
      if (n >= t)
        n = t;
    } else {
      n -= zp.porta_speed[v];
      if (n < t)
        n = t;
    }
    set_note(reg, v, n);
  }
  pulse_sweep(reg, v);
  if (zp.gate_off[v] == --zp.dur[v] || !zp.gate_count[v]) {
    reg[CTRL] = zp.ctrl[v] & ~GATE;
    ++zp.gate_count[v];
  }
  --zp.gate_count[v];
  if (!zp.dur[v])
    read_pattern(reg, v);
}

/* Sweep the cutoff between its limits, reversing at either; the limit
 * tests compare the high byte for (in)equality first, as the original. */
static void filter_sweep(void) {
  uint16_t c = zp.cutoff;
  uint8_t s = zp.cutoff_speed, down = !cutoff_dir;
  for (;;) {
    if (down) {
      uint8_t borrow = (uint8_t)c < s;
      c -= s;
      if (!borrow || !(c & 0x8000))
        if (c >> 8 != cutoff_min_hi || (uint8_t)c >= cutoff_min_lo)
          break;
      --cutoff_dir;
    }
    c += s;
    if (c >> 8 < cutoff_max_hi || (uint8_t)c < cutoff_max_lo)
      break;
    ++cutoff_dir;
    down = 1;
  }
  zp.cutoff = c;
  s = c >> 8;
  SID[FILTER_L] = c;
  SID[FILTER_H] = (uint8_t)(s << 5) | s >> 4 | (uint8_t)c >> 3;
}

void tune_play(void) {
  uint8_t v;
  /* 6502: no loop; voice copies at $6234/$6421/$6610 chained by JMP,
   * identical up to operand strides (+1 zp, +2 zp words, +7 SID, +$1ED/$1EF
   * own operands) and a CMP #v voice 0 omits. */
  for (v = 0; v < 3; ++v)
    play_voice(v);
  filter_sweep();
}

static void copy_block(uint8_t n) {
  uint8_t i = n << 1;
  uint16_t src = peek16(BLOCK_SRC + i), dst = peek16(BLOCK_DST + i);
  uint16_t k, len = peek16(BLOCK_LEN + i);
  for (k = 0; k != len; ++k) /* 6502 loop $29C6-$29E0 */
    poke(dst + k, peek(src + k));
}

static void music_init(uint8_t song) {
  uint8_t v, x, r = SID_REGS;
  copy_block(peek(SONG_BLOCK_A + song));
  copy_block(peek(SONG_BLOCK_B + song));
  x = peek(SONG_INDEX + song);
  while (r--) { /* 6502 loop $61AA */
    SID[r] = 8;
    SID[r] = 0;
  }
  for (r = 0; r < sizeof zp; ++r)
    ((uint8_t *)&zp)[r] = 0;
  cutoff_dir = 0;
  /* 6502: unrolled stores, $6153-$61A5 and into each voice copy's operands
   * at $61BF-$61D9. */
  for (v = 0; v < 3; ++v) {
    fixed_dur[v] = raw_notes[v] = 0;
    pulse_dir[v] = 1;
    zp.ptr[v] = peek(SONG_PTRS + 14 * v + x) | peek(SONG_PTRS + 14 * v + 7 + x)
                                                   << 8;
    zp.active[v] = zp.gate_off[v] = 0xff;
    zp.dur[v] = 1;
    zp.pulse[v] = 0x300;
  }
  cutoff_min_hi = 0;
  cutoff_min_lo = 0x32;
  cutoff_max_hi = 4;
  cutoff_max_lo = 0xcd;
}

static void effect_init(uint8_t x) {
  static const uint8_t off[] = {5, 6, 0xc, 0xd, 0x13, 0x14};
  uint16_t p = peek(EFFECT_LO + x) | peek(EFFECT_HI + x) << 8;
  uint8_t y = 0, v;
  SID[VOLUME] = 0xf;
  for (v = 0; v < sizeof off; ++v) /* 6502: six stores, $7328-$7337 */
    SID[off[v]] = 0;
  /* 6502 loop $61E9-$622B; X picks the voice copy's operand to patch through
   * the table at $622E/$6231. */
  while (!((v = peek(p + y)) & 0x80)) {
    v >>= 1;
    zp.ptr[v] = peek(p + y + 1) | peek(p + y + 2) << 8;
    y += 3;
    zp.active[v] = zp.gate_time[v] = zp.gate_off[v] = 0xff;
    zp.dur[v] = zp.hard_gate[v] = 1;
    fixed_dur[v] = 0;
    zp.transpose[v] = zp.trill_step[v] = zp.trill_up[v] = 0;
    zp.trill_down[v] = zp.vib_delay[v] = zp.vib_speed[v] = 0;
    zp.vib_width[v] = zp.vib_dir_start[v] = 0;
  }
}

void tune_init(uint8_t song) {
  uint8_t i;
  for (i = 0; i <= offsetof(struct state, gate_off); ++i)
    ((uint8_t *)&zp)[i] = 0;
  if ((int8_t)(song - EFFECT_FIRST) < 0)
    music_init(song);
  else
    effect_init(song - EFFECT_BASE);
}
